package greeter

import "strings"

// Slug 把一段文本转成小写、以单个连字符分隔的 slug。
// 首尾空白被去掉，连续空白折成一个连字符。
func Slug(s string) string {
	return strings.ToLower(strings.Join(strings.Fields(s), "-"))
}

package greeter

import "testing"

func TestSlug(t *testing.T) {
	cases := []struct {
		name string
		in   string
		want string
	}{
		{"lowercases and joins", "Hello World", "hello-world"},
		{"trims outer whitespace", "  Hello World  ", "hello-world"},
		{"collapses runs of whitespace", "a   b", "a-b"},
	}
	for _, c := range cases {
		if got := Slug(c.in); got != c.want {
			t.Errorf("%s: Slug(%q) = %q, want %q", c.name, c.in, got, c.want)
		}
	}
}
